use super::event::{Envelope, Event, Outcome, RecordedContent, RecordedResult};
use rmcp::model::{CallToolRequestParams, ContentBlock};
use serde::Serialize;
use serde_json::{Map, Value, json};
use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};

const MARKDOWN_HEADER: &str = r#"# MCP Console recording transcript

<!-- Generated by MCP Console. Do not edit. -->

Calls and results span all worker sessions in this recording.
Session source links open QMD files containing code and environment metadata.

Results record response assembly; transport write evidence is retained separately in capture/events.jsonl.

"#;
pub(super) struct Writers {
    markdown: ProjectionWriter,
    directory: PathBuf,
    documents: Documents,
}
struct ProjectionWriter {
    writer: BufWriter<File>,
    header_written: bool,
    description: &'static str,
}
/// Retain only source and notes awaiting association and each worker's document.
#[derive(Default)]
struct Documents {
    calls: BTreeMap<u64, PendingSource>,
    pending_notes: BTreeMap<u64, QuartoEntry>,
    sessions: BTreeMap<u64, QuartoWriter>,
    metadata: Metadata,
    current: Option<u64>,
}
struct PendingSource {
    admitted: bool,
    entry: QuartoEntry,
}
#[derive(Clone, Default)]
struct Metadata {
    working_directory: String,
    requirements: Value,
    r_requirements: Vec<String>,
    python_requirements: Vec<String>,
    dynamic_resolution: bool,
    r_available: bool,
    metadata_known: bool,
}
struct QuartoWriter {
    metadata: Metadata,
    // Source association can arrive after later notes. Call IDs preserve the
    // submitted order independently of worker acquisition and dispatch.
    entries: BTreeMap<u64, QuartoEntry>,
}
struct QuartoEntry {
    note: Option<String>,
    sources: Vec<QuartoSource>,
}
struct QuartoSource {
    language: &'static str,
    contents: String,
}
impl Writers {
    pub(super) fn new(
        directory: &Path,
        working_directory: &Path,
        dynamic_resolution: bool,
        r_available: bool,
        requirements: &crate::worker_client::Declaration,
        metadata_known: bool,
    ) -> Result<Self, String> {
        let markdown = super::create_private_file(&directory.join("transcript.md"))
            .map_err(|e| e.to_string())?;
        Ok(Self {
            markdown: ProjectionWriter::new(markdown, "Markdown transcript"),
            directory: directory.to_owned(),
            documents: Documents {
                metadata: Metadata {
                    working_directory: working_directory
                        .to_str()
                        .ok_or("source metadata requires a UTF-8 working directory")?
                        .into(),
                    requirements: serde_json::to_value(requirements).map_err(|e| e.to_string())?,
                    r_requirements: requirements.r.clone(),
                    python_requirements: requirements.python.clone(),
                    dynamic_resolution,
                    r_available,
                    metadata_known,
                },
                ..Default::default()
            },
        })
    }
    pub(super) fn relocate(&mut self, directory: &Path) -> Result<(), String> {
        self.markdown.writer = BufWriter::new(
            std::fs::OpenOptions::new()
                .append(true)
                .open(directory.join("transcript.md"))
                .map_err(|e| e.to_string())?,
        );
        self.directory = directory.to_owned();
        Ok(())
    }
    pub(super) fn append(&mut self, event: &Envelope<'_>) -> Result<(), String> {
        let mut fragment = String::new();
        render_event(&mut fragment, event)?;
        if let Some(id) = self.documents.observe(&event.event)? {
            let document = &self.documents.sessions[&id];
            if document.has_contents() {
                let path = self.directory.join(format!("sessions/session-{id:03}.qmd"));
                let first = !path.exists();
                super::replace_private_file(
                    &path,
                    document.render(&format!("session-{id:03}.qmd")).as_bytes(),
                )?;
                if first {
                    writeln!(
                        fragment,
                        "[Session {id:03} source (QMD)](<sessions/session-{id:03}.qmd>)
"
                    )
                    .unwrap();
                }
            }
        }
        self.markdown.append(MARKDOWN_HEADER, &fragment)?;
        Ok(())
    }
}
impl Documents {
    fn observe(&mut self, event: &Event<'_>) -> Result<Option<u64>, String> {
        match event {
            Event::EnvironmentDiscovered {
                dynamic_resolution,
                r_available,
                startup_requirements,
                ..
            } => {
                self.metadata.metadata_known = true;
                self.metadata.dynamic_resolution = *dynamic_resolution;
                self.metadata.r_available = *r_available;
                self.metadata.requirements(
                    &serde_json::to_value(startup_requirements).map_err(|e| e.to_string())?,
                );
                return Ok(self.update_current_metadata());
            }
            Event::WorkerStarted {
                session_id,
                requirements,
                ..
            } => {
                self.metadata.requirements(requirements);
                self.current = Some(*session_id);
                self.sessions.insert(
                    *session_id,
                    QuartoWriter {
                        metadata: self.metadata.clone(),
                        entries: std::mem::take(&mut self.pending_notes),
                    },
                );
                return Ok(Some(*session_id));
            }
            Event::WorkerEnded { .. } => self.current = None,
            Event::ToolCall {
                call_id, request, ..
            } => {
                // The journal owns full requests. Retain only document content,
                // never stdin or request metadata.
                let mut entry = QuartoEntry {
                    note: None,
                    sources: Vec::new(),
                };
                if let Some(arguments) = &request.arguments {
                    entry.note = arguments
                        .get("note")
                        .and_then(Value::as_str)
                        .map(str::to_owned);
                    for language in ["r", "python", "sql"] {
                        if let Some(contents) = arguments.get(language).and_then(Value::as_str) {
                            entry.sources.push(QuartoSource {
                                language,
                                contents: contents.into(),
                            });
                        }
                    }
                }
                if !entry.sources.is_empty() {
                    self.calls.insert(
                        *call_id,
                        PendingSource {
                            admitted: false,
                            entry,
                        },
                    );
                } else if entry.note.is_some() {
                    // Source-free notes describe the current session. Before
                    // acquisition, keep them for the next actual worker; notes
                    // alone do not invent a worker lifetime or start execution.
                    if let Some(session_id) = self.current {
                        self.sessions
                            .get_mut(&session_id)
                            .expect("current worker document")
                            .entries
                            .insert(*call_id, entry);
                        return Ok(Some(session_id));
                    }
                    self.pending_notes.insert(*call_id, entry);
                }
            }
            Event::SourceAdmitted { call_id } => {
                if let Some(pending) = self.calls.get_mut(call_id) {
                    pending.admitted = true;
                }
            }
            Event::SourceFinished { call_id } => {
                self.calls.remove(call_id);
            }
            Event::SourceAssociated {
                call_id,
                session_id,
            } => {
                if let Some(pending) = self.calls.remove(call_id) {
                    self.sessions
                        .get_mut(session_id)
                        .ok_or("associated source has no session")?
                        .entries
                        .insert(*call_id, pending.entry);
                    return Ok(Some(*session_id));
                }
            }
            Event::ToolResult { call_id, .. } => {
                // Response assembly can precede the admitted cell's worker.
                // Keep that source until association or actual settlement.
                if self
                    .calls
                    .get(call_id)
                    .is_some_and(|pending| !pending.admitted)
                {
                    self.calls.remove(call_id);
                }
            }
            Event::RequirementsAccepted { requirements } => {
                self.metadata.requirements(requirements);
                return Ok(self.update_current_metadata());
            }
            // Selection and Python preparation can describe a replacement
            // before the old worker retires. Only live commits and actual
            // acquisition update session metadata.
            Event::RequirementsSelected { .. }
            | Event::PythonEnvironmentAccepted { .. }
            | Event::RecordingStarted { .. }
            | Event::RecordingActivated
            | Event::RecordingEnded
            | Event::Protocol { .. }
            | Event::Delivery { .. }
            | Event::WorkerReady { .. }
            | Event::CellStarted { .. }
            | Event::CellEnded { .. }
            | Event::OutputText { .. }
            | Event::ImageOmitted { .. }
            | Event::ImageRetained { .. }
            | Event::ProcessOutput { .. }
            | Event::StartupFailed { .. }
            | Event::CellOutput { .. }
            | Event::SessionOutput { .. } => {}
        }
        Ok(None)
    }

    fn update_current_metadata(&mut self) -> Option<u64> {
        let id = self.current?;
        self.sessions
            .get_mut(&id)
            .expect("current worker document")
            .metadata = self.metadata.clone();
        Some(id)
    }
}
fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .map(|a| {
            a.iter()
                .filter_map(Value::as_str)
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default()
}
impl Metadata {
    fn requirements(&mut self, value: &Value) {
        if !value.is_null() {
            self.requirements = value.clone();
            self.r_requirements = strings(&value["r"]);
            self.python_requirements = strings(&value["python"]);
        }
    }
}
impl QuartoWriter {
    fn has_contents(&self) -> bool {
        !self.entries.is_empty()
    }
    fn render(&self, filename: &str) -> String {
        let mut document = String::from(
            "---
# Source recorded by MCP Console; review before executing.
title: MCP Console session
",
        );
        writeln!(
            document,
            "# From a working copy, run `ir render {filename}` in a prepared environment.
# IR rendering requires R on the render host, including for Python-only documents."
        )
        .unwrap();
        if !self.metadata.metadata_known {
            document.push_str(
                "execute:
  eval: false
",
            );
        }
        if !self.metadata.metadata_known {
            document.push_str(
                "mcp-console:
  environment: unknown
",
            );
        } else {
            document.push_str(
                "ir:
  isolated: true
",
            );
            push_yaml_sequence(&mut document, "  packages", &self.metadata.r_requirements);
            push_yaml_sequence(
                &mut document,
                "  python-packages",
                &self.metadata.python_requirements,
            );
            document.push_str(
                "mcp-console:
  original-working-directory: ",
            );
            document.push_str(&yaml_string(&self.metadata.working_directory));
            document.push('\n');
            writeln!(
                document,
                "  r-available: {}
  dynamic-resolution: {}",
                self.metadata.r_available, self.metadata.dynamic_resolution
            )
            .unwrap();
            push_yaml_sequence(
                &mut document,
                "  duckdb-extensions",
                &strings(&self.metadata.requirements["duckdb"]),
            );
            push_yaml_sequence(
                &mut document,
                "  python-version",
                &strings(&self.metadata.requirements["python_version"]),
            );
            if let Some(value) = self.metadata.requirements["exclude_newer"].as_str() {
                writeln!(document, "  exclude-newer: {}", yaml_string(value)).unwrap();
            }
        }
        document.push_str(
            "---

",
        );
        for entry in self.entries.values() {
            if let Some(note) = &entry.note {
                push_note(&mut document, note);
            }
            for source in &entry.sources {
                push_quarto_fence(
                    &mut document,
                    &format!("{{{}}}", source.language),
                    source.language,
                    &source.contents,
                );
            }
        }
        document
    }
}
fn push_yaml_sequence(document: &mut String, name: &str, values: &[String]) {
    if values.is_empty() {
        writeln!(document, "{name}: []").expect("writing to a String cannot fail");
        return;
    }
    writeln!(document, "{name}:").expect("writing to a String cannot fail");
    for value in values {
        let value = yaml_string(value);
        writeln!(document, "    - {value}").expect("writing to a String cannot fail");
    }
}

fn yaml_string(value: &str) -> String {
    if is_plain_yaml_string(value) {
        value.to_string()
    } else {
        let json = serde_json::to_string(value).expect("serializing a string cannot fail");
        let mut yaml = String::with_capacity(json.len());
        for character in json.chars() {
            match character {
                '\u{0085}' => yaml.push_str("\\N"),
                '\u{2028}' => yaml.push_str("\\L"),
                '\u{2029}' => yaml.push_str("\\P"),
                '\u{007f}'..='\u{009f}' => {
                    write!(yaml, "\\x{:02X}", character as u32)
                        .expect("writing to a String cannot fail");
                }
                '\u{feff}' | '\u{fffe}' | '\u{ffff}' => {
                    write!(yaml, "\\u{:04X}", character as u32)
                        .expect("writing to a String cannot fail");
                }
                _ => yaml.push(character),
            }
        }
        yaml
    }
}

fn is_plain_yaml_string(value: &str) -> bool {
    let Some(first) = value.chars().next() else {
        return false;
    };
    if !matches!(first, 'A'..='Z' | 'a'..='z' | '_' | '/')
        || value.chars().any(char::is_control)
        || value.chars().any(|character| {
            matches!(
                character,
                '\u{0085}' | '\u{2028}' | '\u{2029}' | '\u{feff}' | '\u{fffe}' | '\u{ffff}'
            )
        })
        || value.trim() != value
        || value.ends_with(':')
        || value
            .chars()
            .zip(value.chars().skip(1))
            .any(|(previous, character)| previous.is_whitespace() && character == '#')
        || value
            .split(':')
            .skip(1)
            .any(|suffix| suffix.starts_with(char::is_whitespace))
    {
        return false;
    }
    !matches!(
        value.to_ascii_lowercase().as_str(),
        "null" | "true" | "false"
    )
}

impl ProjectionWriter {
    fn new(file: File, description: &'static str) -> Self {
        Self {
            writer: BufWriter::new(file),
            header_written: false,
            description,
        }
    }

    fn append(&mut self, header: &str, fragment: &str) -> Result<(), String> {
        if !self.header_written {
            self.writer
                .write_all(header.as_bytes())
                .map_err(|error| format!("failed to append {}: {error}", self.description))?;
        }
        self.writer
            .write_all(fragment.as_bytes())
            .and_then(|()| self.writer.flush())
            .map_err(|error| format!("failed to append {}: {error}", self.description))?;
        self.header_written = true;
        Ok(())
    }
}

fn render_event(document: &mut String, envelope: &Envelope<'_>) -> Result<(), String> {
    match &envelope.event {
        Event::Protocol { .. }
        | Event::Delivery { .. }
        | Event::RecordingActivated
        | Event::OutputText { .. }
        | Event::SourceAdmitted { .. }
        | Event::SourceFinished { .. }
        | Event::SourceAssociated { .. }
        | Event::CellStarted { .. }
        | Event::CellEnded { .. }
        | Event::WorkerReady { .. }
        | Event::ImageOmitted { .. }
        | Event::RequirementsAccepted { .. }
        | Event::PythonEnvironmentAccepted { .. }
        | Event::EnvironmentDiscovered { .. } => Ok(()),
        Event::RecordingEnded => {
            document.push_str(
                "## Recording finished

",
            );
            Ok(())
        }
        Event::ProcessOutput { .. } => Ok(()),
        Event::WorkerStarted {
            session_id, pid, ..
        } => {
            writeln!(
                document,
                "## Session {session_id:03} started

Worker process {pid}.
"
            )
            .unwrap();
            Ok(())
        }
        Event::WorkerEnded { session_id, .. } => {
            writeln!(
                document,
                "## Session {session_id:03} ended
"
            )
            .unwrap();
            Ok(())
        }
        Event::RecordingStarted {
            working_directory, ..
        } => {
            let metadata = json!({
                "run_id": envelope.run_id,
                "started_at": envelope.at,
                "working_directory": working_directory,
            });
            document.push_str(
                "## Console process

",
            );
            push_json(document, &metadata)
        }
        Event::RequirementsSelected {
            call_id,
            action,
            snapshot,
        } => {
            document.push_str(
                "## Requirements selected

",
            );
            push_json(
                document,
                &json!({"call_id": call_id, "action": action, "snapshot": snapshot}),
            )
        }
        Event::ToolCall {
            call_id, request, ..
        } => render_tool_call(document, *call_id, request),
        Event::ImageRetained {
            artifact_id,
            call_id,
            path,
            ..
        } => {
            let owner = call_id.map_or_else(|| "session".into(), |id| format!("call {id}"));
            writeln!(
                document,
                "## Image {artifact_id} for {owner}

[Image {artifact_id} from {owner}](<{path}>)
"
            )
            .expect("writing to a String cannot fail");
            Ok(())
        }
        Event::SessionOutput {
            path,
            retained_bytes,
            discarded_bytes,
            ..
        } => {
            if *retained_bytes != 0 || *discarded_bytes != 0 {
                writeln!(
                    document,
                    "## Session output

[Startup and idle output](<{path}>)

{retained_bytes} raw bytes retained; {discarded_bytes} raw bytes not retained in this file.
"
                )
                .expect("writing to a String cannot fail");
            }
            Ok(())
        }
        Event::StartupFailed { message, .. } => {
            document.push_str(
                "## Startup failed

",
            );
            push_fence(document, "text", message);
            Ok(())
        }
        Event::CellOutput {
            call_id,
            path,
            retained_bytes,
            inline_omitted_bytes,
            discarded_bytes,
            ..
        } => {
            if *inline_omitted_bytes != 0 || *discarded_bytes != 0 {
                writeln!(
                    document,
                    "## Retained output for call {call_id}

[Retained text output for call {call_id}](<{path}>)

{retained_bytes} raw bytes retained; {inline_omitted_bytes} rendered UTF-8 bytes omitted from inline responses; {discarded_bytes} raw bytes not retained in this file.
"
                )
                .expect("writing to a String cannot fail");
            }
            Ok(())
        }
        Event::ToolResult {
            call_id, outcome, ..
        } => render_tool_result(document, *call_id, outcome),
    }
}

fn render_tool_call(
    document: &mut String,
    call_id: u64,
    request: &CallToolRequestParams,
) -> Result<(), String> {
    let Some(send) = parse_send(request) else {
        writeln!(
            document,
            "## Call {call_id}: Tool request
"
        )
        .expect("writing to a String cannot fail");
        if let Some(source) = submitted_source(request) {
            push_fence(document, source.language, source.contents);
            document.push_str(
                "### Raw request

",
            );
        }
        return push_json(document, request);
    };

    let label = send.label();
    writeln!(
        document,
        "## Call {call_id}: {label}
"
    )
    .expect("writing to a String cannot fail");
    if let Some(note) = send.note {
        push_note(document, note);
    }
    if let Some(source) = send.source {
        push_fence(document, source.language, source.contents);
    }
    if let Some(stdin) = send.stdin {
        document.push_str(
            "### Submitted stdin

",
        );
        push_fence(document, "text", stdin);
    }
    if !send.options.is_empty() {
        document.push_str(
            "### Options

",
        );
        push_json(document, &Value::Object(send.options))?;
    }
    Ok(())
}

struct Send<'a> {
    source: Option<Source<'a>>,
    note: Option<&'a str>,
    stdin: Option<&'a str>,
    options: Map<String, Value>,
}

impl Send<'_> {
    fn label(&self) -> &'static str {
        if let Some(source) = self.source {
            return source.label;
        }
        match self.options.get("control").and_then(Value::as_str) {
            Some("interrupt") => return "Interrupt",
            Some("restart") => return "Restart",
            _ => {}
        }
        if self.stdin.is_some() {
            return "Stdin";
        }
        if self.options.contains_key("requirements") {
            return "Requirements";
        }
        if self.note.is_some() {
            return "Note";
        }
        if self.options.is_empty() || self.options.keys().all(|key| key == "timeout_ms") {
            "Poll"
        } else {
            "Send"
        }
    }
}

#[derive(Clone, Copy)]
struct Source<'a> {
    label: &'static str,
    language: &'static str,
    contents: &'a str,
}

fn submitted_source(request: &CallToolRequestParams) -> Option<Source<'_>> {
    if request.name != "send" {
        return None;
    }
    let arguments = request.arguments.as_ref()?;
    let mut source = None;
    for (field, label, language) in [
        ("r", "R", "r"),
        ("python", "Python", "python"),
        ("sql", "SQL", "sql"),
    ] {
        let Some(value) = arguments.get(field) else {
            continue;
        };
        if value.is_null() {
            continue;
        }
        let value = value.as_str()?;
        if source
            .replace(Source {
                label,
                language,
                contents: value,
            })
            .is_some()
        {
            return None;
        }
    }
    source
}

fn parse_send(request: &CallToolRequestParams) -> Option<Send<'_>> {
    if request.name != "send"
        || request.input_responses.is_some()
        || request.request_state.is_some()
    {
        return None;
    }
    let arguments = match request.arguments.as_ref() {
        Some(arguments) => arguments,
        None => {
            return Some(Send {
                source: None,
                note: None,
                stdin: None,
                options: Map::new(),
            });
        }
    };
    if arguments.keys().any(|key| {
        !matches!(
            key.as_str(),
            "r" | "python" | "sql" | "note" | "stdin" | "control" | "requirements" | "timeout_ms"
        )
    }) {
        return None;
    }
    let source = submitted_source(request);
    if source.is_none()
        && arguments
            .iter()
            .any(|(key, value)| matches!(key.as_str(), "r" | "python" | "sql") && !value.is_null())
    {
        return None;
    }
    let stdin = match arguments.get("stdin") {
        Some(Value::Null) | None => None,
        Some(stdin) => Some(stdin.as_str()?),
    };
    let note = match arguments.get("note") {
        Some(Value::Null) | None => None,
        Some(note) => Some(note.as_str()?),
    };
    let options = arguments
        .iter()
        .filter(|(key, _)| !matches!(key.as_str(), "r" | "python" | "sql" | "note" | "stdin"))
        .filter(|(key, value)| {
            !matches!(key.as_str(), "control" | "requirements") || !value.is_null()
        })
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    Some(Send {
        source,
        note,
        stdin,
        options,
    })
}

fn render_tool_result(
    document: &mut String,
    call_id: u64,
    outcome: &Outcome<'_>,
) -> Result<(), String> {
    writeln!(
        document,
        "## Result for call {call_id}
"
    )
    .expect("writing to a String cannot fail");
    match outcome {
        Outcome::Result { result } => render_result(document, call_id, result),
        Outcome::Error { error } => {
            document.push_str(
                "### Tool error

",
            );
            push_json(document, error)
        }
    }
}

fn render_result(
    document: &mut String,
    call_id: u64,
    result: &RecordedResult<'_>,
) -> Result<(), String> {
    if result.is_error == Some(true) {
        document.push_str(
            "### Tool result error

",
        );
    }
    if result.content.is_empty() {
        document.push_str(
            "_No content._

",
        );
    }
    for block in &result.content {
        match block {
            RecordedContent::Text(text) => push_fence(document, "text", &text.text),
            RecordedContent::Image {
                artifact_id: Some(artifact_id),
                path: Some(path),
                ..
            } => {
                writeln!(
                    document,
                    "![Image {artifact_id}](<{path}>)
"
                )
                .expect("writing to a String cannot fail");
            }
            RecordedContent::Image { .. } => document.push_str(
                "_Image not retained._

",
            ),
            RecordedContent::Other(content) => {
                let kind = match content {
                    ContentBlock::Text(_) => "text",
                    ContentBlock::Image(_) => "image",
                    ContentBlock::Audio(_) => "audio",
                    ContentBlock::Resource(_) => "resource",
                    ContentBlock::ResourceLink(_) => "resource_link",
                    _ => "unknown",
                };
                return Err(format!(
                    "Markdown transcript has unsupported content kind {kind:?} for call {call_id}"
                ));
            }
        }
    }
    Ok(())
}

fn push_json(document: &mut String, value: &(impl Serialize + ?Sized)) -> Result<(), String> {
    let json = serde_json::to_string_pretty(value)
        .map_err(|error| format!("failed to render Markdown transcript JSON: {error}"))?;
    push_fence(document, "json", &json);
    Ok(())
}

fn push_fence(document: &mut String, language: &str, contents: &str) {
    push_fence_with_prefix(document, language, "", contents);
}

fn push_note(document: &mut String, note: &str) {
    document.push_str(note);
    if !note.ends_with('\n') {
        document.push('\n');
    }
    document.push('\n');
}

fn push_quarto_fence(document: &mut String, language: &str, source_language: &str, contents: &str) {
    let comment = if source_language == "sql" { "--" } else { "#" };
    let mut prefix = format!(
        "{comment}| error: true
"
    );
    if starts_with_quarto_cell_option(source_language, contents) {
        prefix.push('\n');
    }
    push_fence_with_prefix(document, language, &prefix, contents);
}

fn starts_with_quarto_cell_option(language: &str, contents: &str) -> bool {
    let comment = match language {
        "r" | "python" => "#",
        "sql" => "--",
        _ => return false,
    };
    let first_line = contents.split_once('\n').map_or(contents, |(line, _)| line);
    first_line
        .trim_start()
        .strip_prefix(comment)
        .map(str::trim_start)
        .is_some_and(|line| line.starts_with('|'))
}

fn push_fence_with_prefix(document: &mut String, language: &str, prefix: &str, contents: &str) {
    let longest = contents
        .split(|character| character != '`')
        .map(str::len)
        .max()
        .unwrap_or_default();
    let fence = "`".repeat((longest + 1).max(3));
    writeln!(document, "{fence}{language}").expect("writing to a String cannot fail");
    document.push_str(prefix);
    document.push_str(contents);
    if !contents.ends_with('\n') {
        document.push('\n');
    }
    writeln!(
        document,
        "{fence}
"
    )
    .expect("writing to a String cannot fail");
}
